 for(let i=0;i<args.length;i++){const k=args[i];if(!k.startsWith('--')||!allowed.has(k.slice(2))||opts[k.slice(2)]!==undefined)throw Error('Unknown or repeated argument: '+k);const value=args[++i];if(!value||value.startsWith('--'))throw Error('Missing value for '+k);opts[k.slice(2)]=value;}
